// PlanServiceHandler is an implementation of the ezdr.portal.v1.PlanService service.
type PlanServiceHandler interface {
	ListPlans(context.Context, *connect.Request[v1.ListPlansRequest]) (*connect.Response[v1.ListPlansResponse], error)
	GetPlan(context.Context, *connect.Request[v1.GetPlanRequest]) (*connect.Response[v1.GetPlanResponse], error)
	CreatePlan(context.Context, *connect.Request[v1.CreatePlanRequest]) (*connect.Response[v1.CreatePlanResponse], error)
	UpdatePlan(context.Context, *connect.Request[v1.UpdatePlanRequest]) (*connect.Response[v1.UpdatePlanResponse], error)
	DeletePlan(context.Context, *connect.Request[v1.DeletePlanRequest]) (*connect.Response[v1.DeletePlanResponse], error)
	// ValidatePlan checks a specification without saving it.
	ValidatePlan(context.Context, *connect.Request[v1.ValidatePlanRequest]) (*connect.Response[v1.ValidatePlanResponse], error)
	// SuggestPlan fills in missing mappings, startup order, and defaults.
	SuggestPlan(context.Context, *connect.Request[v1.SuggestPlanRequest]) (*connect.Response[v1.SuggestPlanResponse], error)
	// ListZreplSetups lists existing hand-written zrepl setups between a plan's
	// hosts that the plan could adopt.
	ListZreplSetups(context.Context, *connect.Request[v1.ListZreplSetupsRequest]) (*connect.Response[v1.ListZreplSetupsResponse], error)
	// AdoptZreplSetup fills in a specification from an existing zrepl setup,
	// without saving it.
	AdoptZreplSetup(context.Context, *connect.Request[v1.AdoptZreplSetupRequest]) (*connect.Response[v1.AdoptZreplSetupResponse], error)
	// RunTakeoverPreflight checks, on both hosts, that an adopted plan can take
	// over its zrepl setup, and stores the result. It changes nothing on the
	// hosts.
	RunTakeoverPreflight(context.Context, *connect.Request[v1.RunTakeoverPreflightRequest]) (*connect.Response[v1.RunTakeoverPreflightResponse], error)
	// GetTakeover returns an adopted plan's latest preflight and takeover
	// progress.
	GetTakeover(context.Context, *connect.Request[v1.GetTakeoverRequest]) (*connect.Response[v1.GetTakeoverResponse], error)
	// StartTakeover takes over the zrepl setup after a recent preflight without
	// problems. It returns once the takeover has started; GetTakeover shows its
	// progress. On success the plan becomes active.
	StartTakeover(context.Context, *connect.Request[v1.StartTakeoverRequest]) (*connect.Response[v1.StartTakeoverResponse], error)
	// RetryTakeoverRollback runs the rollback of a failed takeover again, for
	// example once an offline host is back.
	RetryTakeoverRollback(context.Context, *connect.Request[v1.RetryTakeoverRollbackRequest]) (*connect.Response[v1.RetryTakeoverRollbackResponse], error)
	// PreviewPlanChanges lists what activating or applying the plan's
	// editing specification would change on each host.
	PreviewPlanChanges(context.Context, *connect.Request[v1.PreviewPlanChangesRequest]) (*connect.Response[v1.PreviewPlanChangesResponse], error)
	// ActivatePlan applies a valid draft to its hosts.
	ActivatePlan(context.Context, *connect.Request[v1.ActivatePlanRequest]) (*connect.Response[v1.ActivatePlanResponse], error)
	// ApplyPlanChanges applies an active plan's pending changes.
	ApplyPlanChanges(context.Context, *connect.Request[v1.ApplyPlanChangesRequest]) (*connect.Response[v1.ApplyPlanChangesResponse], error)
	// DiscardPlanChanges reverts pending changes to the applied specification.
	DiscardPlanChanges(context.Context, *connect.Request[v1.DiscardPlanChangesRequest]) (*connect.Response[v1.DiscardPlanChangesResponse], error)
	PausePlan(context.Context, *connect.Request[v1.PausePlanRequest]) (*connect.Response[v1.PausePlanResponse], error)
	ResumePlan(context.Context, *connect.Request[v1.ResumePlanRequest]) (*connect.Response[v1.ResumePlanResponse], error)
	// DeactivatePlan removes the plan's jobs from its hosts and returns it to
	// draft. Replicas and snapshots are kept.
	DeactivatePlan(context.Context, *connect.Request[v1.DeactivatePlanRequest]) (*connect.Response[v1.DeactivatePlanResponse], error)
	// GetPlanStatus returns an active plan's replication health.
	GetPlanStatus(context.Context, *connect.Request[v1.GetPlanStatusRequest]) (*connect.Response[v1.GetPlanStatusResponse], error)
}

